import{_ as t,o as d,c as o,a5 as c}from"./chunks/framework.BMR-TWOq.js";const b=JSON.parse('{"title":"Sport Client — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/sport-client.md","filePath":"ko/software/sdk/cpp/sport-client.md","lastUpdated":1794576042000}'),a={name:"ko/software/sdk/cpp/sport-client.md"};function s(i,e,n,l,r,p){return d(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="sport-client-—-c-예제" tabindex="-1">Sport Client — C++ 예제 <a class="header-anchor" href="#sport-client-—-c-예제" aria-label="Permalink to &quot;Sport Client — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq/rbq_sport_client.cpp</code></p><p><strong>SportClient</strong> 명령을 하나씩 로봇에 전송하는 터미널 기반 대화형 애플리케이션입니다.<br> 명령 이름(또는 숫자 ID)을 입력하고 Enter 를 누르면 그 명령을 한 번 보냅니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><p>프로그램은 단일 루프로 동작합니다:</p><ol><li><code>stdin</code>에서 한 줄 입력 받기 (<code>list</code>, 명령 이름, 또는 명령 ID).</li><li>현재 <code>test_option</code> 업데이트.</li><li>해당 <code>SportClient</code> 메서드를 한 번 호출하고 다음 줄을 기다림.</li></ol><p>별도의 제어 스레드 없이 터미널 읽기가 Enter 키 입력까지 블로킹되는 단순한 순차 테스트 방식입니다.</p><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중(시뮬레이션 또는 하드웨어)이며 동일 네트워크에서 접근 가능해야 합니다.</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리 위치: <code>bin-x86_64/rbq_sport_client</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_sport_client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 시뮬레이터 / 로봇 내부 스택 — 인터페이스 기본값은 lo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_sport_client</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 실제 로봇 — 로봇에 닿는 인터페이스를 넘깁니다</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin-x86_64/rbq_sport_client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><h2 id="사용-가능한-명령" tabindex="-1">사용 가능한 명령 <a class="header-anchor" href="#사용-가능한-명령" aria-label="Permalink to &quot;사용 가능한 명령&quot;">​</a></h2><p>프롬프트에서 <code>list</code>를 입력하면 전체 명령 목록이 출력되고, 숫자 ID를 바로 입력해도 됩니다.</p><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>호출되는 SportClient 메서드</th></tr></thead><tbody><tr><td>0</td><td><code>damp</code></td><td><code>Damp()</code> — 고댐핑 비상 정지</td></tr><tr><td>1</td><td><code>balance_stand</code></td><td><code>BalanceStand()</code> — 균형 서기</td></tr><tr><td>2</td><td><code>stop_move</code></td><td><code>StopMove()</code> — 제자리 정지</td></tr><tr><td>3</td><td><code>stand_down</code></td><td><code>StandDown()</code> — 엎드리기</td></tr><tr><td>4</td><td><code>recovery_stand</code></td><td><code>RecoveryStand()</code> — 넘어짐 후 일어서기</td></tr><tr><td>5</td><td><code>move</code></td><td><code>Move(0.0, 0.0, 0.5)</code> — 제자리 회전</td></tr><tr><td>6</td><td><code>switch_gait</code></td><td><code>SwitchGait(0)</code> — 걷기 보행(<code>49</code>)으로 전환</td></tr><tr><td>7</td><td><code>speed_level</code></td><td><code>SpeedLevel(1)</code> — 빠르게: <code>move</code> 속도 × 1.5</td></tr><tr><td>8</td><td><code>get_state</code></td><td><code>GetState()</code> — 로봇 상태 출력</td></tr><tr><td>9</td><td><code>body_height</code></td><td><code>BodyHeight(-0.1)</code> — 몸 10 cm 낮추기</td></tr><tr><td>10</td><td><code>stand_up</code></td><td><code>StandUp()</code> — 서기 자세로 관절 고정</td></tr><tr><td>11</td><td><code>enter_leftside_gait</code></td><td><code>LeftSideGait(1)</code></td></tr><tr><td>12</td><td><code>exit_leftside_gait</code></td><td><code>LeftSideGait(0)</code> — 걷기 보행(<code>49</code>)으로 복귀</td></tr><tr><td>13</td><td><code>enter_handstand</code></td><td><code>HandStand(1)</code> — <code>RL_FRONT_WALK</code>(31) 정책으로 전환</td></tr><tr><td>14</td><td><code>exit_handstand</code></td><td><code>HandStand(0)</code> — 걷기 보행(<code>49</code>)으로 복귀</td></tr><tr><td>15</td><td><code>pose</code></td><td><code>BodyPosition(0.0, 0.0, -0.1, 0.2)</code> — 몸 10 cm 낮추고 0.2 rad 돌리기</td></tr><tr><td>16</td><td><code>euler</code></td><td><code>Euler(0.2, 0.3, 0.3)</code> — 몸 기울이기(roll·pitch·yaw, 라디안)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>ID 11–14 는 넓은 곳에서 시험하세요 — 예제 소스가 이 명령들에 &quot;Caution: test in open area&quot; 를 달아 두었습니다.</p></div><blockquote><p>모든 명령이 <code>code: 0</code> 으로 찍힙니다 — <code>SetNoReply(true)</code> 라 로봇의 응답을 기다리지 않습니다. 응답이 필요한 <code>get_state</code> 만 기다립니다.</p></blockquote><blockquote><p><code>move</code>·<code>body_height</code>·<code>pose</code>·<code>euler</code> 는 제어 모드가 HighLevel 일 때만 먹습니다. 예제는 시작할 때 <code>rt/rbq/cmd/switch_control_mode</code> 에 <code>true</code> 를 발행해 켭니다(ROS <a href="/RBQ/nightly/ko/software/sdk/ros/topics.html#rbq-cmd-switch-control-mode"><code>/rbq/cmd/switch_control_mode</code></a>). 게임패드 스틱을 움직이면 다시 꺼집니다. 꺼져 있으면 로봇이 <code>0</code> 대신 <code>3205</code>(거부)로 답합니다 — 예제는 <code>SetNoReply(true)</code> 라 이 답을 보지 않습니다. <code>move</code> 는 걷기 보행도 켜져 있어야 하므로 <code>move</code> 전에 <code>switch_gait</code>(6)를 먼저 실행하세요.</p></blockquote><blockquote><p><code>switch_gait</code> 는 걷기 보행 <code>49</code> 로 바꿉니다. <code>SwitchGait(1)</code>(달리기)도 같은 보행입니다 — <code>49</code> 는 1.3 m/s 를 넘으면 빠른 정책으로 알아서 바뀝니다. <code>SwitchGait(2)</code>(오르기)는 비전 걷기 <code>48</code> 로 바꾸는데, 지형을 로봇의 비전으로 봅니다. 비전이 꺼져 있으면 지형 정보 없이 그대로 걷고 경고도 없습니다. 옆걸음·물구나무를 끝내면 <code>49</code> 로 돌아갑니다.</p></blockquote><blockquote><p><code>Euler(roll, pitch, yaw)</code> 는 라디안입니다. <code>BodyHeight(h)</code> 와 <code>BodyPosition(x, y, z, yaw)</code> 의 <code>z</code> 는 기본 높이에서의 차이(m), <code>yaw</code> 는 라디안입니다. 서 있을 때(보행 <code>1</code>)는 roll ±25°, pitch ±20°, yaw ±25°, 높이 −0.15~+0.05 m 를 따릅니다. 걸을 때(<code>48</code>·<code>49</code>)는 pitch(±25°)와 높이(−0.25~+0.1 m)만 따릅니다. 범위를 넘는 값은 잘립니다. 자세는 <code>move</code>·<code>stop_move</code> 를 해도 유지되고, <code>stand_up</code>·<code>stand_down</code>·<code>balance_stand</code>·<code>recovery_stand</code>·<code>damp</code> 를 하면 수평으로 돌아갑니다. 앱·비상정지 같은 다른 경로로 로봇이 앉거나 넘어지거나 멈추면 SDK 가 자세를 버리고 다음 <code>move</code>·<code>stop_move</code> 에서 몸을 수평으로 돌립니다 — 그 전에 HighLevel 모드로 다시 세우면 마지막 자세로 설 수 있습니다. 로봇은 몸을 앞뒤·좌우로 옮기지 못하므로 <code>BodyPosition</code> 은 <code>x</code>·<code>y</code> 가 <code>0</code> 이 아니면 <code>3204</code>(파라미터 오류)를 돌려줍니다.</p></blockquote><blockquote><p><code>SpeedLevel(-1)</code> 은 느리게, <code>0</code> 은 보통(기본값), <code>1</code> 은 빠르게입니다 — 로봇이 <code>move</code> 속도에 0.5·1·1.5 를 곱합니다. 보행마다 정해진 최대 속도는 그대로 적용됩니다. 로봇 소프트웨어를 다시 켜면 <code>0</code> 으로 돌아갑니다.</p></blockquote><blockquote><p><code>get_state</code> 는 로봇의 응답을 한 줄에 키 하나씩 출력합니다:</p></blockquote><table tabindex="0"><thead><tr><th>키</th><th>값</th></tr></thead><tbody><tr><td><code>fsm_id</code></td><td>현재 보행 ID(<a href="/RBQ/nightly/ko/software/sdk/ros/reference.html#gait-state-id">Gait State ID</a>)</td></tr><tr><td><code>fsm_name</code></td><td>현재 보행 이름</td></tr><tr><td><code>speed_level</code></td><td><code>-1</code>, <code>0</code>, <code>1</code></td></tr><tr><td><code>control_mode</code></td><td><code>1</code> HighLevel, <code>0</code> 조이스틱</td></tr><tr><td><code>is_standing</code></td><td><code>1</code> 또는 <code>0</code></td></tr><tr><td><code>is_fall</code></td><td><code>1</code> 또는 <code>0</code></td></tr></tbody></table><h2 id="사용-예" tabindex="-1">사용 예 <a class="header-anchor" href="#사용-예" aria-label="Permalink to &quot;사용 예&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ./bin-x86_64/rbq_sport_client eth0</span></span>
<span class="line"><span>Input &quot;list &quot; to list all test option ...</span></span>
<span class="line"><span>balance_stand</span></span>
<span class="line"><span>Test: balance_stand, test_id: 1</span></span>
<span class="line"><span>Request successed: balance_stand, code: 0</span></span>
<span class="line"><span>move</span></span>
<span class="line"><span>Test: move, test_id: 5</span></span>
<span class="line"><span>Request successed: move, code: 0</span></span></code></pre></div><h2 id="주요-구현-사항" tabindex="-1">주요 구현 사항 <a class="header-anchor" href="#주요-구현-사항" aria-label="Permalink to &quot;주요 구현 사항&quot;">​</a></h2><ul><li><strong>SetNoReply(true)</strong>: <code>SportClient</code>는 <code>SetNoReply(true)</code>로 초기화됩니다. 각 요청을 RPC 응답 대기 없이 DDS 발행 방식으로 전송합니다 — WiFi 환경에서의 고주파 제어에 적합합니다.</li><li><strong>한 줄에 요청 하나</strong>: <code>std::getline</code>이 Enter 를 누를 때까지 블로킹되므로, 입력한 줄마다 요청을 하나씩 보냅니다 — 명령을 반복해서 보내지 않습니다.</li><li><strong>에러 카운팅</strong>: <code>res_count</code> 변수가 연속 실패를 누적하여 에러 코드와 함께 출력합니다.</li></ul><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/sdk/cpp/sport-client-joy.html">Sport Client (조이스틱)</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a></li></ul>`,32)])])}const k=t(a,[["render",s]]);export{b as __pageData,k as default};
